    function lockToken(
        address _tokenAddress,
        address _withdrawalAddress,
        uint256 _amount,
        uint256 _unlockTime,
        bool _mintNFT
    ) external payable returns (uint256 _id);

    function extendLockDuration(uint256 _id, uint256 _unlockTime) external;
}

